-- GENERATED by supabase/seed.py — edit that file, not this one.
-- Demo data for the beta. Every insert is idempotent; demo tickets are reset on each run.

on conflict (id) do update set name = excluded.name, ticket_prefix = excluded.ticket_prefix, send_from_email = excluded.send_from_email, send_from_name = excluded.send_from_name, bench_address = coalesce(workspaces.bench_address, excluded.bench_address);

on conflict (id) do nothing;

-- ---------------------------------------------------------------- catalog (demo)
on conflict (id) do update set model = excluded.model, reference = excluded.reference, warranty_months = excluded.warranty_months, is_active = true;

on conflict do nothing;

on conflict (id) do update set sku = excluded.sku, name = excluded.name, component = excluded.component, unit_cost = excluded.unit_cost, reorder_at = excluded.reorder_at, is_active = true;

-- Fits are pure demo configuration: reset them for the demo watches.
delete from watch_parts where watch_id in ('a0000000-0000-4000-8000-000000000101', 'a0000000-0000-4000-8000-000000000102', 'a0000000-0000-4000-8000-000000000103', 'a0000000-0000-4000-8000-000000000104', 'a0000000-0000-4000-8000-000000000111', 'a0000000-0000-4000-8000-000000000112', 'a0000000-0000-4000-8000-000000000121');
on conflict do nothing;

-- The stock ledger is reset to the opening counts on every run (all parts are demo parts).
-- Rows on tickets created through the app are unlinked first so they don't block the reset.
update ticket_parts set stock_movement_id = null, used_at = null where stock_movement_id is not null;
delete from part_orders;
delete from stock_movements;
-- Legacy demo tickets from the first seed.
delete from tickets where id in ('a0000000-0000-4000-8000-000000000401', 'a0000000-0000-4000-8000-000000000402', 'a0000000-0000-4000-8000-000000000403', 'a0000000-0000-4000-8000-000000000404', 'a0000000-0000-4000-8000-000000000405', 'a0000000-0000-4000-8000-000000000406');
on conflict (id) do nothing;

-- Reorders in progress for two of the out-of-stock parts.

-- ---------------------------------------------------------------- demo people
-- Every demo sign-in uses the password 'PivotDemo2026!!'. Re-running the seed resets it.
on conflict (id) do update set encrypted_password = excluded.encrypted_password, email_confirmed_at = coalesce(auth.users.email_confirmed_at, now());

on conflict (provider_id, provider) do nothing;

on conflict (id) do update set display_name = excluded.display_name, is_active = true;

on conflict (user_id, role, workspace_id, brand_id) do nothing;

